import sys; sys.path.insert(0, '_tools'); from spec import enrich
enrich('el-equilibrio', 'B',
 [dict(t=2202, e=2246, titulo='El problema de los extremos está en el oído', txt='La enfermedad del extremista es un problema en su oído. ¿Qué representa para nosotros, los cristianos, el oído? […] La fe es la certeza de lo que se espera y la convicción de lo que no se ve; pero la fe se recibe por lo que oímos. Si tenemos un problema de oído, tenemos un problema de extremos.'),
  dict(t=2903, e=2947, titulo='Escuchar a Dios nos equilibra', txt='Escuchar la voz de Dios es de vida o muerte, hermano. Debería ser una necesidad imperante en todos los días de nuestra vida. No estoy diciendo escuchar una prédica, porque alguien podría escuchar la prédica y no escuchar la voz de Dios. Es que Dios nos esté hablando. Nos puede hablar en su Palabra, en un sueño, en una profecía, en un mensaje, en nuestro espíritu; pero la cosa es escucharlo. Y cuando lo escuchamos, nos equilibra.'),
  dict(t=3604, e=3652, titulo='Los que no escuchan viven por costumbre', txt='Dios le quiere hablar a usted, hermano. Nosotros tenemos que tener el oído atento todo el tiempo: «Señor, ¿qué es lo que tú me quieres decir? Háblame.» No sé si usted tiene esa necesidad; yo sí la tengo, que Dios me hable. Segunda de Reyes 17:40, mire el peligro: «Ellos no escucharon, sino que hicieron conforme a su antigua costumbre.» Tremendo, hermano: los que no escuchan a Dios viven por costumbres.')],
 [dict(t=1009, txt='El evangelio espiritual no se pelea con el sentido común. Si lo espiritual está peleando en contra del sentido común, no es espiritual.'),
  dict(t=2949, txt='Todavía nos estamos yendo muy por un lado y el Señor dice: «No, no, no. Para este lado.» Y hasta que agarramos el equilibrio, ya vamos bien.'),
  dict(t=3869, txt='Solamente el Espíritu Santo es el que nos puede, de veras, equilibrar.')],
 ['«El evangelio espiritual no se pelea con el sentido común.» ¿En qué área de tu vida te estás yendo hacia un extremo?',
  'El pastor dice que escuchar la voz de Dios es «de vida o muerte». ¿Cómo estás cultivando hoy el oído atento a Dios, más allá de una prédica?',
  '«Los que no escuchan a Dios viven por costumbres.» ¿Qué costumbre religiosa le pedirías al Señor que reemplace con convicción?'],
 inicio=189)
